import math as m9

def prime_sieve(n):
	if n % 2 == 1:
		n += 1
	sieve = [True] * int(n / 2)
	n2 = sqrt_int(n)
	for i in range(3, n2 + 1, 2):
		if sieve[int(i / 2)]:
			sieve[int(i * i / 2)::i] = [False] * int((n - i * i - 1) / (2 * i) + 1)
	return [2] + [2 * i + 1 for i in range(1, int(n / 2)) if sieve[i]]

def sqrt_int(n):
	n2 = int(n ** 0.5)
	if (n2 + 1) ** 2 == n:
		print('         sqrt_int: rounding issues for n = 8d, n2 = %9.4f' % (n, n2))
	return n2

def issq(n):
	if n < 0:
		print('issq-error - CANNOT calc the square root of n = %8.3f' % n)
	valid = n == verifytruncatednthroot(n, 2) ** 2
	return valid

def verifytruncatednthroot(n, root):
	n1 = n ** (1 / root)
	n2 = int(n1)
	check1 = (n2 + 1) ** root
	if check1 <= n:
		n2 += 1
	check2 = (n2 + 0) ** root
	if check2 > n:
		print('         verifytruncatednthroot: ROUNDING issue(2)', n, root, n1, n2, check2)
	return n2

def primefactorsuptop_typ2(n, primes):
	v = []
	k = n
	for q in primes:
		while k % q == 0:
			v.append(q)
			k //= q
	if k > 1:
		v.append(k)
	return v

