			p = max(r1, r2)
			q = min(r1, r2)
			g = m9.gcd(p, q)
			if g > 1:
				f1 = p // g
				if f1 in G11 and p in G11:
					G11.remove(p)
	G = list(G11)
	R1 = []
	for r in R0:
